<?php
defined('ABSPATH')||exit;
final class GDO_Retention{
    public function hooks(){add_action('gdo_daily_retention',array($this,'run'));}
    public function run(){global $wpdb;GDO_Rate_Limiter::cleanup();$now=current_time('mysql',true);$expiring=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.GDO_Schema::table('applications')." WHERE state IN ('verified','reinstated') AND verified_until IS NOT NULL AND verified_until<%s LIMIT 100",$now));foreach($expiring as $app){GDO_State::transition($app->id,'expired',0,'verification_expired','Verification validity period ended.',$app->row_version);GDO_Notifications::queue('doctor_verification_expired',$app->user_id,array('application_id'=>$app->id));} $ring=GDO_Crypto::keyring();if(!is_wp_error($ring)){$rotate=$wpdb->get_col($wpdb->prepare('SELECT id FROM '.GDO_Schema::table('evidence')." WHERE envelope_version='GDO2' AND key_id<>%s AND deleted_at IS NULL LIMIT 25",$ring['active']));foreach($rotate as $evidence_id)GDO_Evidence::rotate_key($evidence_id);}$apps=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.GDO_Schema::table('applications')." WHERE legal_hold=0 AND retention_until IS NOT NULL AND retention_until<%s LIMIT 100",$now));foreach($apps as $app){if(in_array($app->state,array('verified','reinstated','under_review','recommended','appeal_pending'),true))continue;foreach(GDO_Evidence::records($app->id,true) as $record){$proof=GDO_Storage::delete_verified($record->storage_name,$record->ciphertext_sha256);if(!is_wp_error($proof))$wpdb->update(GDO_Schema::table('evidence'),array('retention_state'=>'deleted','deletion_proof'=>$proof,'deleted_at'=>$now,'storage_name'=>'deleted-'.$record->id,'updated_at'=>$now),array('id'=>$record->id),array('%s','%s','%s','%s','%s'),array('%d'));}}$wpdb->query($wpdb->prepare('UPDATE '.GDO_Schema::table('access_log')." SET reviewer_id=0,purpose_code='anonymized' WHERE created_at<%s",gmdate('Y-m-d H:i:s',time()-365*DAY_IN_SECONDS)));do_action('gdo_retention_completed',$now);}
}
